import React, { useState } from 'react';
import { View, Image, StyleSheet, Text, Pressable } from 'react-native';

const Outdoor_CLG = ({ route, navigation }) => {
    const [rowGap, setRowGap] = useState(10);
    const [colGap, setColGap] = useState(10);

    return (
        <View style={styles.container}>
            <View style={styles.navbuttoncontainer}>
                <Text style={{ color: 'white', fontSize: 50 }}>Which Sport?</Text>
            </View>
            <View style={styles.orangebutton}>
                <Text style={{ color: 'black', fontSize: 40 }}>College: Indoor</Text>
            </View>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View style={styles.imageContainer}>
                    <Image
                        style={styles.appdim}
                        resizeMode='contain'
                        source={require('/assets/basketBallGame.png')}
                    />
                </View>
            </Pressable>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View style={styles.imageContainer}>
                    <Image
                        style={styles.appdim}
                        resizeMode='contain'
                        source={require('/assets/CricketGame.png')}
                    />
                </View>
            </Pressable>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View style={styles.imageContainer}>
                    <Image
                        style={styles.appdim}
                        resizeMode='contain'
                        source={require('/assets/TennisGame.png')}
                    />
                </View>
            </Pressable>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View style={styles.imageContainer}>
                    <Image
                        style={styles.appdim}
                        resizeMode='contain'
                        source={require('/assets/FootballGame.png')}
                    />
                </View>
            </Pressable>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View style={styles.imageContainer}>
                    <Image
                        style={styles.appdim}
                        resizeMode='contain'
                        source={require()}
                    />
                </View>
            </Pressable>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View style={styles.imageContainer}>
                    <Image
                        style={styles.appdim}
                        resizeMode='contain'
                        source={require('/assets/basketBallGame.png')}
                    />
                </View>
            </Pressable>
            <Pressable onPress={() => console.log('Image pressed')}>
                <View style={styles.imageContainer}>
                    <Image
                        style={styles.appdim}
                        resizeMode='contain'
                        source={require('/assets/basketBallGame.png')}
                    />
                </View>
            </Pressable>
                    
            
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: 'black',
    },
    navbuttoncontainer: {
        justifyContent: 'center',
        alignItems: 'center',
        height: 50,
    },
    orangebutton: {
        justifyContent: 'flex-start',
        alignItems: 'center',
        width: 200,
        height: 100,
        borderRadius: 100,
        borderWidth: 20,
    },
    imageContainer: {
        flexDirection: 'row',
        flexWrap: 'wrap',
        justifyContent: 'center',
    },
    appdim: {
        height: 100,
        width: 50,
        margin: 5,
    },
});

export default Outdoor_CLG;
